// Snippet 1: Iterator Invalidation - Vector (Contiguous Storage)
// Inserting/Erasing elements can cause reallocation or shifting,
// invalidating iterators and pointers.

std::vector<int> v = {10, 20, 30};
auto it = v.begin() + 1; // Points to 20

// 1. Insertion (may cause reallocation)
v.insert(v.begin(), 5);
// Danger: 'it' is likely invalidated (UB if used)

// 2. Erase (safe only if re-assigned)
auto safe_it = v.begin() + 1;
safe_it = v.erase(safe_it); // safe_it is updated to point to the next element (30)

// Standard rule: `vector::erase` returns the valid iterator following the removed element.


// Snippet 2: Iterator Invalidation - List (Node-Based Storage)
// Insertion does not invalidate iterators; only erasing a specific node invalidates its iterator.

std::list<int> l = {10, 20, 30};
auto it_20 = l.begin();
std::advance(it_20, 1); // Points to 20

// Insertion does NOT invalidate existing iterators
l.push_back(40);
// 'it_20' is still valid, pointing to 20

// Erase returns the valid iterator following the removed element
auto it_10 = l.begin();
it_10 = l.erase(it_10); // it_10 now points to 20 (it_20 is still valid)

// Key safety: Iterators to node-based containers are robust to size changes.


// Snippet 3: Custom Forward Iterator Implementation (Minimal)

template<typename T>
struct CustomPtrIterator {
    using iterator_category = std::forward_iterator_tag;
    using difference_type = std::ptrdiff_t;
    using value_type = T;
    T* ptr;

    T& operator*() const { return *ptr; }

    // Prefix increment
    CustomPtrIterator& operator++() { ++ptr; return *this; }

    // Postfix increment
    CustomPtrIterator operator++(int) {
        CustomPtrIterator temp = *this;
        ++ptr; return temp;
    }

    bool operator==(const CustomPtrIterator& other) const { return ptr == other.ptr; }
};
